def solve(inputs: dict) -> float:
    n = inputs.get('n', inputs.get('people', inputs.get('count')))
    k = inputs.get('k', inputs.get('step', inputs.get('every')))
    if n is None or k is None:
        raise KeyError('Expected n (number of people) and k (elimination step)')
    n, k = int(n), int(k)
    if n < 1 or k < 1:
        raise ValueError('n and k must be positive')
    survivor = 0
    for size in range(2, n + 1):
        survivor = (survivor + k) % size
    return survivor + 1

